/**
 * Shared positioning constants for Menu components (MenuSingleSelect, MenuMultiSelect).
 *
 * Single source of truth for the values that control dropdown gap, edge buffering,
 * and scroll area sizing across the four files that implement Menu positioning:
 *   - MenuSingleSelect.tsx
 *   - MenuDropdownContainer.tsx
 *   - MenuMultiSelect.tsx
 *   - MenuDropdownContainerMultiple.tsx
 */

/** Gap between the trigger's bottom edge and the dropdown top when opening below. */
var MENU_BELOW_GAP = 4;

/**
 * Gap between the trigger's top edge and the dropdown bottom when opening above.
 * SingleSelect uses this value (10px) for open-air clearance.
 * MultiSelect uses MENU_MULTI_ABOVE_GAP (4px) — see that constant for explanation.
 */
var MENU_ABOVE_GAP = 10;

/**
 * Above-gap for MultiSelect only — tighter than MENU_ABOVE_GAP.
 * MultiSelect's Apply/Cancel footer sits at the bottom of the dropdown. When the menu
 * opens above the trigger, the footer faces the trigger and provides its own visual
 * frame, making 4px sufficient. The footer height is accounted for separately via the
 * `overhead` calculation (menu.offsetHeight - scrollAreaEl.offsetHeight).
 */
var MENU_MULTI_ABOVE_GAP = 4;

/** Minimum distance between the dropdown and any viewport edge (shift middleware). */
var MENU_EDGE_BUFFER = 8;

/**
 * Default maximum height for the scroll area when no maxHeight prop is provided.
 * Matches the CSS default in MenuSingleSelect.module.scss.
 */
var MENU_DEFAULT_MAX_HEIGHT = 270;

/**
 * Minimum available viewport space (px) before applying the scroll area height cap.
 * Below this threshold the browser handles overflow naturally.
 */
var MENU_MIN_AVAILABLE_SPACE = 100;

/**
 * Floor for the scroll area's max-height (px).
 * Prevents the scroll area from collapsing to an unusable size.
 */
var MENU_MIN_SCROLL_AREA_HEIGHT = 60;

export { MENU_ABOVE_GAP, MENU_BELOW_GAP, MENU_DEFAULT_MAX_HEIGHT, MENU_EDGE_BUFFER, MENU_MIN_AVAILABLE_SPACE, MENU_MIN_SCROLL_AREA_HEIGHT, MENU_MULTI_ABOVE_GAP };
